import{_ as o,c as d,e as a,a as i,b as t,d as n,w as e,r as p,o as h}from"./app-CHV3pEDi.js";const c="/assets/p3-DteV0tLC.png",k="/assets/%E5%8E%9F%E5%9B%A0%E4%B8%80tick%E5%91%A8%E6%9C%9F%E5%81%8F%E5%B7%AE-pGU82HH7.jpg",g="/assets/%E5%8E%9F%E5%9B%A0%E4%BA%8C%E8%B0%83%E5%BA%A6%E5%BB%B6%E8%BF%9F-D3FlINul.jpg",m="/assets/%E5%8E%9F%E5%9B%A0%E4%B8%89%E4%B8%AD%E6%96%AD%E5%BD%B1%E5%93%8D-fyhpFLw5.jpg",u="/assets/%E5%8E%9F%E5%9B%A0%E5%9B%9B%E4%B8%B4%E7%95%8C%E5%8C%BA%E5%BD%B1%E5%93%8D-TVyVQWyp.jpg",y={};function A(T,s){const r=p("font"),l=p("VPLink");return h(),d("div",null,[s[7]||(s[7]=a('<p>在实际开发中，由于RTOS提供了任务延时函数，很自然地，这些函数成为任务中常用的API之一。</p><blockquote><p>比如，在RT-Thread中，我们可以使用rt_thread_mdelay(10)来延时10毫秒。</p></blockquote><p>不过，很多同学在实际调试时会发现一个问题：</p><blockquote><p><strong>rt_thread_mdelay(10)实际延时的时间，不一定正好是10毫秒。有时候不到10毫秒、有时候可能是11毫秒、有时候甚至更长。</strong></p></blockquote><p>为什么会出现这种情况？</p><p>今天，在这篇文章中，我将深入分析造成这一问题的原因。</p><h2 id="rtos延时的基本原理" tabindex="-1"><a class="header-anchor" href="#rtos延时的基本原理"><span>RTOS延时的基本原理</span></a></h2><p>要理解为什么RTOS的延时不准确，我们首先要搞清楚RTOS的延时是怎么实现的。</p><p>这里以RT-Thread为例，其延时机制如下图所示： <img src="'+c+'" alt="p3.png"></p><p>具体来说：</p><ol><li>RTOS会配置一个硬件定时器（比如SysTick），让它周期（如1000Hz）地产生中断，即<strong>tick中断</strong>。</li><li>每次tick中断时，RTOS做两件事：更新系统时间，同时检查延时队列中的任务是否到期。</li><li>当任务调用rt_thread_mdelay(10)时，RTOS计算出需要等待10个tick，将任务挂到延时队列上。</li><li>当tick中断发生时，RTOS遍历延时队列，将到期的任务移回就绪队列。</li><li>当调度器调度到这个任务时，任务才从延时函数中返回，继续执行后面的代码。</li></ol><p><strong>由此可见，RTOS的延时不是直接让CPU&quot;干等&quot;指定时间，而是基于系统tick的&quot;间接延时&quot;。</strong></p>',12)),i("p",null,[s[1]||(s[1]=t("换句话说，",-1)),n(r,{color:"#245bdb"},{default:e(()=>[...s[0]||(s[0]=[i("strong",null,"延时函数的本质是让任务等待指定的tick中断次数，而不是精确等待指定的时间",-1)])]),_:1}),s[2]||(s[2]=t("。",-1))]),s[8]||(s[8]=a('<h2 id="延时不精确的几个原因" tabindex="-1"><a class="header-anchor" href="#延时不精确的几个原因"><span>延时不精确的几个原因</span></a></h2><p>具体来说，RTOS延时不精确主要有以下几个原因。</p><h3 id="tick中断周期的限制" tabindex="-1"><a class="header-anchor" href="#tick中断周期的限制"><span>tick中断周期的限制</span></a></h3><p>这是最根本的原因。</p><p>我们知道，<strong>RTOS的延时是以tick中断周期为单位的，延时时间只能是tick的整数倍</strong>。</p><p>假设tick频率是1000Hz（即1ms一个tick），那么当调用rt_thread_mdelay(10)时，RTOS会让任务等待10个tick。</p><p>不过，调<strong>用延时函数的时刻，并不能保证一定能在tick发生时，而是会有所偏差</strong>。</p><p>例如，调用时机距离下一个tick中断可能还有0.9ms，也可能只有0.1ms，这将使得实际的延时可能是9.1ms或9.9ms。</p><p><img src="'+k+'" alt="原因一tick周期偏差"></p><p><strong>在最坏的情况下，实际延时时间可能相差接近一个tick（1ms）。</strong></p><h3 id="调度延迟" tabindex="-1"><a class="header-anchor" href="#调度延迟"><span>调度延迟</span></a></h3><p><strong>当任务延时到期后，任务被移回就绪队列，但这不意味着任务会立即运行。</strong></p><p>此时，如果有<strong>更高优先级的任务正在运行，那么刚到期的任务只能等待，直到高优先级任务阻塞或结束</strong>。这段等待时间就是调度延迟，时间长度可能是几个tick甚至更长。</p><p>例如，当一个高优先级任务正在执行一个耗时20ms的操作时，任务需要再等20ms才能运行，这就使得实际延时就是30ms而不是10ms。</p><p><img src="'+g+'" alt="原因二调度延迟"></p><h3 id="中断影响" tabindex="-1"><a class="header-anchor" href="#中断影响"><span>中断影响</span></a></h3><p>由于中断的优先级比任何任务都高，中断触发时CPU会立即响应中断，暂停当前任务的执行，也会打断调度器的执行。</p><p>如果中断处理时间较长，或者中断频繁发生，会导致tick中断本身被延迟响应，延时到期的检查也会被推迟。</p><p>同时，中断也会延迟调度器的调度，进一步增加延时误差。</p><p><img src="'+m+`" alt="原因三中断影响"></p><h3 id="临界区影响" tabindex="-1"><a class="header-anchor" href="#临界区影响"><span>临界区影响</span></a></h3><p>在某些情况下，多个任务需要访问共享的资源，为避免访问冲突会暂时关闭中断或锁定调度器，从而进入临界区。</p><p>在临界区期间，tick中断不会被响应，延时到期的检查也不会执行。<strong>如果临界区执行时间较长，会导致延时到期检查被推迟，影响其它任务的延时</strong>。</p><p>下面给出RT-Thread中临界区的简单示例：</p><div class="language-c line-numbers-mode" data-highlighter="shiki" data-ext="c" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-c"><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> critical_section_example</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">void</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* 进入临界区，锁定调度器，任务切换被禁止 */</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    rt_enter_critical</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* 访问共享资源，此时即使tick中断到来，</span></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">       也不会触发任务调度，当前任务继续执行 */</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    process</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">();</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">   // 比较耗时的操作 </span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    /* 退出临界区，恢复调度器 */</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">    rt_exit_critical</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">();</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在rt_enter_critical()和rt_exit_critical()之间，调度器被锁定，任务切换不会发生。</p><p><strong>如果这段临界区的执行时间较长，其他任务的延时到期检查就会被推迟，导致实际延时变长</strong>。</p><p><img src="`+u+'" alt="原因四临界区影响"></p><h2 id="最坏情况" tabindex="-1"><a class="header-anchor" href="#最坏情况"><span>最坏情况</span></a></h2><p>由此可见，我们可知：<strong>任务延时函数并不能保证比较准确的延时</strong>。</p><p>甚至于在高优先级任务长时间占用CPU的情况下，任务希望延时10ms，实际延时到期后，任务迟迟无法运行。</p><p><strong>因此，延时的最坏情况，可以说是没有上限的。</strong></p><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>综上所述，<strong>RTOS中的延时不一定精确，其根本原因在于延时是基于系统tick中断，而不是直接让CPU等待指定时间</strong>。</p><p>那么，如何实现更精确的延时，我将在后续文章中详细介绍，欢迎持续关注！</p><hr>',36)),i("blockquote",null,[s[4]||(s[4]=i("p",null,"如果你希望系统地学习RTOS底层原理，可以了解我的《RTOS开发与实战》课程。",-1)),s[5]||(s[5]=i("p",null,"课程不是简单地讲解FreeRTOS API的使用，而是带你从零开始编写一个RTOS内核，逐步实现任务管理、任务调度、上下文切换、同步与通信等核心机制，并通过一个远程温湿度监控设备项目，将操作系统原理应用到实际嵌入式开发中。",-1)),s[6]||(s[6]=i("p",null,"适合希望深入理解RTOS工作原理、提升嵌入式底层开发能力的同学。",-1)),i("p",null,[n(l,{href:"/blog/diyrtos/"},{default:e(()=>[...s[3]||(s[3]=[t("课程详情",-1)])]),_:1})])])])}const v=o(y,[["render",A]]),E=JSON.parse('{"path":"/tech/rtos100/p9t50jd5/","title":"为什么RTOS中的延时不一定精确","lang":"zh-CN","frontmatter":{"title":"为什么RTOS中的延时不一定精确","createTime":"2026/11/10 14:55:17","permalink":"/tech/rtos100/p9t50jd5/","description":"在实际开发中，由于RTOS提供了任务延时函数，很自然地，这些函数成为任务中常用的API之一。 比如，在RT-Thread中，我们可以使用rt_thread_mdelay(10)来延时10毫秒。 不过，很多同学在实际调试时会发现一个问题： rt_thread_mdelay(10)实际延时的时间，不一定正好是10毫秒。有时候不到10毫秒、有时候可能是11毫...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"为什么RTOS中的延时不一定精确\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://lishutong1024.cn/tech/rtos100/p9t50jd5/"}],["meta",{"property":"og:site_name","content":"李述铜的嵌入式课堂"}],["meta",{"property":"og:title","content":"为什么RTOS中的延时不一定精确"}],["meta",{"property":"og:description","content":"在实际开发中，由于RTOS提供了任务延时函数，很自然地，这些函数成为任务中常用的API之一。 比如，在RT-Thread中，我们可以使用rt_thread_mdelay(10)来延时10毫秒。 不过，很多同学在实际调试时会发现一个问题： rt_thread_mdelay(10)实际延时的时间，不一定正好是10毫秒。有时候不到10毫秒、有时候可能是11毫..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":5.3,"words":1590},"git":{},"autoDesc":true,"filePathRelative":"notes/tech/rtos100/schedule/q52.md","headers":[],"bulletin":true}');export{v as comp,E as data};
